mapper.insert:
INSERT INTO faq (
	faq_id
				, category_code
				, question
				, answer
				, sort_order
				, use_yn
				, writer_id
				, created_at
				, updated_by
				, updated_at
 )
VALUES (
	#{faqId}
				, #{categoryCode}
				, #{question}
				, #{answer}
				, #{sortOrder}
				, #{useYn}
				, #{writerId}
				, #{createdAt}
				, #{updatedBy}
				, #{updatedAt}
 )

mapper.update:
UPDATE faq
SET				category_code=#{categoryCode}				, question=#{question}
	, answer=#{answer}
	, sort_order=#{sortOrder}
	, use_yn=#{useYn}
	, writer_id=#{writerId}
	, created_at=#{createdAt}
	, updated_by=#{updatedBy}
	, updated_at=#{updatedAt}
WHERE
	faq_id=#{faqId}

mapper.select:
SELECT faq_id , category_code , question , answer , sort_order , use_yn , writer_id , created_at , updated_by , updated_at FROM faq WHERE 1=1
AND faq_id LIKE #{searchPattern}
AND category_code LIKE #{searchPattern}
ORDER BY faq_id DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*) totcnt
FROM faq
WHERE 1=1




			AND faq_id LIKE #{searchPattern}




			AND category_code LIKE #{searchPattern}
